  "Delete the list \"{0}\"?": { fa: "فهرست «{0}» حذف شود؟", ar: "حذف القائمة «{0}»؟", ru: "Удалить список «{0}»?", es: "¿Eliminar la lista «{0}»?", pt: "Apagar a lista «{0}»?", de: "Liste „{0}“ löschen?", fr: "Supprimer la liste « {0} » ?" },
  "Description (optional)": { fa: "توضیح (اختیاری)", ar: "الوصف (اختياري)", ru: "Описание (необязательно)", es: "Descripción (opcional)", pt: "Descrição (opcional)", de: "Beschreibung (optional)", fr: "Description (facultatif)" },
  "Deselect All": { fa: "لغو انتخاب همه", ar: "إلغاء تحديد الكل", ru: "Снять выделение", es: "Deseleccionar todo", pt: "Desmarcar tudo", de: "Auswahl aufheben", fr: "Tout désélectionner" },
