  "Move to another journal": { fa: "انتقال به ژورنال دیگر", ar: "النقل إلى سجل آخر", ru: "Перенести в другой журнал", es: "Mover a otro diario", pt: "Mover para outro diário", de: "In anderes Journal verschieben", fr: "Déplacer vers un autre journal" },
