  "Restart MetaTrader": { fa: "متاتریدر را دوباره باز کن", ar: "أعد تشغيل ميتاتريدر", ru: "Перезапустите MetaTrader", es: "Reinicia MetaTrader", pt: "Reinicia o MetaTrader", de: "MetaTrader neu starten", fr: "Redémarrez MetaTrader" },
