  "Revoke": { fa: "لغو", ar: "إبطال", ru: "Отозвать", es: "Revocar", pt: "Revogar", de: "Widerrufen", fr: "Révoquer" },
  "Revoke this key? Any EA using it will stop sending trades.": { fa: "این کلید لغو شود؟ هر اکسپرتی که از آن استفاده می‌کند دیگر معامله نمی‌فرستد.", ar: "إبطال هذا المفتاح؟ سيتوقف أي خبير يستخدمه عن إرسال الصفقات.", ru: "Отозвать этот ключ? Советники с ним перестанут отправлять сделки.", es: "¿Revocar esta clave? Cualquier EA que la use dejará de enviar operaciones.", pt: "Revogar esta chave? Qualquer EA que a use deixa de enviar operações.", de: "Diesen Schlüssel widerrufen? Jeder EA damit sendet dann keine Trades mehr.", fr: "Révoquer cette clé ? Tout EA qui l'utilise cessera d'envoyer des trades." },
  "Run through your own rules before taking the trade.": { fa: "پیش از ورود به معامله قوانین خودت را مرور کن.", ar: "راجع قواعدك قبل الدخول في الصفقة.", ru: "Пройдитесь по своим правилам перед входом в сделку.", es: "Repasa tus propias reglas antes de entrar en la operación.", pt: "Revê as tuas regras antes de entrar na operação.", de: "Geh deine eigenen Regeln durch, bevor du den Trade eingehst.", fr: "Passez vos propres règles en revue avant de prendre le trade." },
  "Save": { fa: "ذخیره", ar: "حفظ", ru: "Сохранить", es: "Guardar", pt: "Guardar", de: "Speichern", fr: "Enregistrer" },
  "Search or type a symbol... (Enter to add)": { fa: "نماد را جستجو یا تایپ کن... (Enter برای افزودن)", ar: "ابحث عن رمز أو اكتبه... (Enter للإضافة)", ru: "Найдите или введите символ... (Enter — добавить)", es: "Busca o escribe un símbolo... (Enter para añadir)", pt: "Procura ou escreve um símbolo... (Enter para adicionar)", de: "Symbol suchen oder eingeben... (Enter zum Hinzufügen)", fr: "Cherchez ou saisissez un symbole... (Entrée pour ajouter)" },
  "Select All": { fa: "انتخاب همه", ar: "تحديد الكل", ru: "Выбрать все", es: "Seleccionar todo", pt: "Selecionar tudo", de: "Alle auswählen", fr: "Tout sélectionner" },
  "selected": { fa: "انتخاب‌شده", ar: "محدد", ru: "выбрано", es: "seleccionadas", pt: "selecionadas", de: "ausgewählt", fr: "sélectionnés" },
