  "Setup complete": { fa: "نصب کامل شد", ar: "اكتمل التثبيت", ru: "Установка завершена", es: "Instalación completa", pt: "Instalação concluída", de: "Einrichtung abgeschlossen", fr: "Installation terminée" },
  "Setup name...": { fa: "نام ستاپ...", ar: "اسم الإعداد...", ru: "Название сетапа...", es: "Nombre del setup...", pt: "Nome do setup...", de: "Setup-Name...", fr: "Nom du setup..." },
  "Share the reward": { fa: "تقسیم پاداش", ar: "تقاسم المكافأة", ru: "Поделить награду", es: "Repartir la recompensa", pt: "Dividir a recompensa", de: "Prämie teilen", fr: "Partager la récompense" },
  "Sign In": { fa: "ورود", ar: "تسجيل الدخول", ru: "Войти", es: "Iniciar sesión", pt: "Entrar", de: "Anmelden", fr: "Se connecter" },
  "Sign Out": { fa: "خروج", ar: "تسجيل الخروج", ru: "Выйти", es: "Cerrar sesión", pt: "Terminar sessão", de: "Abmelden", fr: "Se déconnecter" },
  "Sign Up": { fa: "ثبت نام", ar: "إنشاء حساب", ru: "Регистрация", es: "Registrarse", pt: "Registar", de: "Registrieren", fr: "S'inscrire" },
  "Standard Setups": { fa: "ستاپ‌های استاندارد", ar: "إعدادات قياسية", ru: "Стандартные сетапы", es: "Setups estándar", pt: "Setups padrão", de: "Standard-Setups", fr: "Setups standard" },
