  "trades — move": { fa: "معامله را منتقل کن", ar: "صفقات — نقل", ru: "сделок — перенести", es: "operaciones — mover", pt: "operações — mover", de: "Trades verschieben", fr: "trades — déplacer" },
  "Transcribing…": { fa: "در حال تبدیل به متن…", ar: "جارٍ التفريغ…", ru: "Расшифровка…", es: "Transcribiendo…", pt: "A transcrever…", de: "Wird transkribiert…", fr: "Transcription…" },
  "Undo": { fa: "بازگردانی", ar: "تراجع", ru: "Отменить", es: "Deshacer", pt: "Desfazer", de: "Rückgängig", fr: "Annuler" },
  "Unlimited access to all features": { fa: "دسترسی نامحدود به همه امکانات", ar: "وصول غير محدود إلى كل الميزات", ru: "Неограниченный доступ ко всем функциям", es: "Acceso ilimitado a todas las funciones", pt: "Acesso ilimitado a todas as funcionalidades", de: "Unbegrenzter Zugang zu allen Funktionen", fr: "Accès illimité à toutes les fonctionnalités" },
  "Unlimited MetaTrader auto-sync": { fa: "ثبت خودکار متاتریدر، نامحدود", ar: "مزامنة ميتاتريدر التلقائية بلا حدود", ru: "Автозапись из MetaTrader без ограничений", es: "Registro automático de MetaTrader ilimitado", pt: "Registo automático do MetaTrader ilimitado", de: "Unbegrenzter MetaTrader-Autoimport", fr: "Synchro MetaTrader illimitée" },
  "Unlimited trades & journals, every day": { fa: "معامله و ژورنال نامحدود، هر روز", ar: "صفقات وسجلات بلا حدود كل يوم", ru: "Неограниченные сделки и журналы каждый день", es: "Operaciones y diarios ilimitados, cada día", pt: "Operações e diários ilimitados, todos os dias", de: "Unbegrenzt Trades & Journale, jeden Tag", fr: "Trades et journaux illimités, chaque jour" },
  "Upgrade to Pro": { fa: "ارتقا به Pro", ar: "الترقية إلى Pro", ru: "Перейти на Pro", es: "Pasar a Pro", pt: "Passar para Pro", de: "Auf Pro upgraden", fr: "Passer à Pro" },
  "Upload failed.": { fa: "بارگذاری ناموفق بود.", ar: "فشل الرفع.", ru: "Не удалось загрузить.", es: "Error al subir.", pt: "Falha no envio.", de: "Hochladen fehlgeschlagen.", fr: "Échec de l'envoi." },
  "Uploading photos...": { fa: "در حال بارگذاری عکس‌ها...", ar: "جارٍ رفع الصور...", ru: "Загрузка фото...", es: "Subiendo fotos...", pt: "A carregar fotos...", de: "Fotos werden hochgeladen...", fr: "Envoi des photos..." },
  "Uploading...": { fa: "در حال بارگذاری...", ar: "جارٍ الرفع...", ru: "Загрузка...", es: "Subiendo...", pt: "A carregar...", de: "Wird hochgeladen...", fr: "Envoi..." },
  "Voice notes & AI analysis": { fa: "یادداشت صوتی و تحلیل هوش مصنوعی", ar: "ملاحظات صوتية وتحليل بالذكاء الاصطناعي", ru: "Голосовые заметки и ИИ-анализ", es: "Notas de voz y análisis con IA", pt: "Notas de voz e análise com IA", de: "Sprachnotizen & KI-Analyse", fr: "Notes vocales et analyse IA" },
  "Warnings": { fa: "هشدارها", ar: "تحذيرات", ru: "Предупреждения", es: "Avisos", pt: "Avisos", de: "Warnungen", fr: "Avertissements" },
  "We cannot show this again — only its hash is stored. If you lose it, create a new one.": { fa: "نمی‌توانیم این را دوباره نشان دهیم — فقط اثر رمزنگاری‌شده‌اش ذخیره می‌شود. اگر گمش کردی، یکی تازه بساز.", ar: "لا يمكننا إظهاره مجدداً — تُحفظ بصمته فقط. إن فقدته فأنشئ مفتاحاً جديداً.", ru: "Мы не сможем показать его снова — хранится только хеш. Если потеряете, создайте новый.", es: "No podremos volver a mostrarla: solo se guarda su hash. Si la pierdes, crea otra.", pt: "Não conseguimos voltar a mostrá-la — só se guarda o hash. Se a perderes, cria outra.", de: "Wir können ihn nicht erneut anzeigen — nur sein Hash wird gespeichert. Verlierst du ihn, erstelle einen neuen.", fr: "Nous ne pourrons plus l'afficher — seule son empreinte est conservée. Si vous la perdez, créez-en une nouvelle." },
  "Which chart should it go on?": { fa: "روی کدام چارت بگذارم؟", ar: "على أي رسم بياني أضعه؟", ru: "На какой график его поставить?", es: "¿En qué gráfico lo pongo?", pt: "Em que gráfico o ponho?", de: "Auf welchen Chart soll es?", fr: "Sur quel graphique le placer ?" },
  "Which journal should the trades go to?": { fa: "معاملات به کدام ژورنال بروند؟", ar: "إلى أي سجل تذهب الصفقات؟", ru: "В какой журнал записывать сделки?", es: "¿A qué diario van las operaciones?", pt: "Para que diário vão as operações?", de: "In welches Journal sollen die Trades?", fr: "Dans quel journal enregistrer les trades ?" },
  "Will be added to your journal:": { fa: "به ژورنالت اضافه می‌شود:", ar: "سيُضاف إلى سجلك:", ru: "Будет добавлено в журнал:", es: "Se añadirá a tu diario:", pt: "Será adicionado ao teu diário:", de: "Wird deinem Journal hinzugefügt:", fr: "Sera ajouté à votre journal :" },
  "Write your {0} analysis — structure, liquidity, key levels...": { fa: "تحلیل {0} را بنویس — ساختار، نقدینگی، سطوح کلیدی...", ar: "اكتب تحليلك على {0} — الهيكل، السيولة، المستويات الرئيسية...", ru: "Напишите анализ {0} — структура, ликвидность, ключевые уровни...", es: "Escribe tu análisis de {0}: estructura, liquidez, niveles clave...", pt: "Escreve a tua análise de {0} — estrutura, liquidez, níveis-chave...", de: "Schreibe deine {0}-Analyse — Struktur, Liquidität, Schlüsselzonen...", fr: "Rédigez votre analyse {0} — structure, liquidité, niveaux clés..." },
  "Writing tidied": { fa: "نوشته اصلاح شد", ar: "صُحّحت الكتابة", ru: "Текст исправлен", es: "Escritura corregida", pt: "Escrita corrigida", de: "Text korrigiert", fr: "Écriture corrigée" },
